export function numero(r: Record<string, unknown>, key: string): number {
  const value = r[key];
  const n =
    typeof value === 'number' || (typeof value === 'string' && value.trim()) ? Number(value) : NaN;
  if (!Number.isFinite(n)) throw new Error('Respuesta del servidor inválida.');
  return n;
}

readonly usuario = computed(() => this.sesion()?.user ?? null);
readonly activo = computed(() => this.perfil()?.activo === true);
readonly autenticado = computed(() => this.usuario() !== null && this.activo() &&
  this.perfil()?.id === this.usuario()?.id);
readonly rol = computed(() => this.autenticado() ? this.perfil()?.rol ?? null : null);

export function rolGuard(...permitidos: Rol[]): CanActivateFn {
  return async (_route, state) => {
    const auth = inject(AuthService);
    const sesion = inject(SesionService);
    const router = inject(Router);
    await auth.refrescarPerfil();
    if (!sesion.autenticado()) {
      return router.createUrlTree(['/auth/login'], { queryParams: { returnUrl: state.url } });
    }
    const rol = sesion.rol();
    return (rol !== null && permitidos.includes(rol)) ||
      router.createUrlTree(['/errores/sin-permiso']);
  };
}

const bs = values.map((codigo) => distribucion().find((b) => b.codigo === codigo));
if (bs.some((b) => !b) || new Set(values).size !== values.length) return { contiguas: true };
const validas = bs.filter((b): b is Butaca => b !== undefined);
return new Set(validas.map((b) => b.fila)).size === 1 &&
  new Set(validas.map((b) => b.bloque)).size === 1 &&
  Math.max(...validas.map((b) => b.columna)) -
    Math.min(...validas.map((b) => b.columna)) +
    1 ===
    validas.length
  ? null
  : { contiguas: true };

